using System;using System.Linq;using System.Collections.Generic;using System.Windows.Media.Media3D;
namespace GearLab {public static class RobotReducerLoads {
 static readonly Dictionary<string,TrainSolution> Models=new Dictionary<string,TrainSolution>();
 static TrainSolution Model(TransmissionTrain t){string key=CADDocument.Serializer().Serialize(t);lock(Models){TrainSolution value;if(Models.TryGetValue(key,out value))return value;value=TrainSolver.Solve(t);if(!value.Valid)throw new Exception(string.Join(";",value.Errors));if(Models.Count>=16)Models.Clear();Models[key]=value;return value;}}
 public static void Apply(RobotBuild build,RobotJoint joint,Dictionary<string,RobotPose> poses,RobotJointLoad state){if(!CompoundReducer.Enabled(joint.TrainSettings)||joint.TrainSettings.Materials==null||joint.Mode==RobotJointMode.Неподвижный)return;var d=build.Document;var pose=poses[joint.Id];Vector3D force=new Vector3D(),moment=new Vector3D();Action<Point3D,Vector3D> add=(point,f)=>{force+=f;moment+=Vector3D.CrossProduct((point-pose.Origin)/1000,f);};foreach(var e in build.Entries.Values.Where(e=>e.OwnerId!=null&&!e.Guide&&d.Descendant(e.OwnerId,joint.Id))){var centre=RobotSolver.Pose(e,poses,d.GripperOpening).Transform(build.CachedCentre(e));add(centre,new Vector3D(0,0,-build.Mass(e)*d.Gravity));}foreach(var tool in d.Joints.Where(t=>d.Descendant(t.Id,joint.Id)))add(RobotSolver.LoadPoint(d,tool,poses),new Vector3D(tool.ForceX,tool.ForceY,tool.ForceZ-tool.Payload*d.Gravity));var radial=force-pose.Axis*Vector3D.DotProduct(force,pose.Axis);var transverse=moment-pose.Axis*Vector3D.DotProduct(moment,pose.Axis);var copy=CADDocument.Serializer().Deserialize<TransmissionTrain>(CADDocument.Serializer().Serialize(joint.TrainSettings));copy.OutputLoad=copy.OutputLoad??new TrainOutputLoad();copy.OutputLoad.RadialForce=radial.Length;copy.OutputLoad.AxialForce=Math.Abs(Vector3D.DotProduct(force,pose.Axis));copy.OutputLoad.OutputTorque=Math.Abs(state.SignedEffort);copy.OutputLoad.ForceOffset=radial.Length>1e-9?transverse.Length*1000/radial.Length:0;copy.OutputLoad.ForceAngle=0;var result=TrainStrength.Calculate(copy,Model(joint.TrainSettings));if(radial.Length<1e-9&&transverse.Length>1e-9){foreach(var m in result.Modes.Where(m=>m.Mode=="Текучесть выходного вала")){m.LimitTorque=null;m.Note="Не определено: чистый поперечный момент не представим радиальной силой на консоли.";}var known=result.Modes.Where(m=>m.LimitTorque.HasValue).OrderBy(m=>m.LimitTorque).FirstOrDefault();result.LimitTorque=known==null?null:known.LimitTorque;result.WeakestPart=known==null?null:known.Part;var structure=result.Modes.Where(m=>m.LimitTorque.HasValue&&m.Mode!="Проскальзывание муфты").OrderBy(m=>m.LimitTorque).FirstOrDefault();result.StructuralLimit=structure==null?null:structure.LimitTorque;result.Shaft=null;result.Notes.Add("Чистый поперечный момент вала не оценён; нужна модель сил и моментов на фланце.");}state.ReducerLimit=result.StructuralLimit??result.LimitTorque;state.ReducerLoads=result;state.StrengthMessage="Предел редуктора по оценённым пунктам: "+(result.LimitTorque.HasValue?Engine.F(result.LimitTorque.Value)+" Н·м":"не определено")+". Нагрузки взяты из текущей позы; эквивалентная консоль по поперечному моменту, осевые реакции зависят от схемы опор.";if(result.LimitTorque.HasValue&&state.Available>result.LimitTorque.Value){state.StrengthMessage+=" Привод способен разрушить собственный редуктор: нужна муфта или другая передача.";state.Message+=" · Привод сильнее редуктора";state.Enough=false;} }
}}
